-- composition of rule kernels CoverIdxScan x PropagateConst (sqlite), template graft_exists
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT CAST(10.0 AS REAL) AS c0, CAST(42.5 AS NUMERIC) AS c1, FALSE AS c2, 2 AS c3 FROM ((SELECT 0 AS c0, '{}' AS c1 FROM (SELECT * FROM t4 WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('abc' AS TEXT) AS c1 FROM t0 AS a1 UNION ALL SELECT FALSE AS c0, CAST('NaN' AS TEXT) AS c1) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('abc' AS TEXT) AS c1 FROM t0 AS a1 UNION ALL SELECT FALSE AS c0, CAST('NaN' AS TEXT) AS c1) AS kb)) AS a1) AS a2 LEFT OUTER JOIN (tp AS a3 JOIN t3 AS a4 ON ((a3.c0 = a4.c0) AND a4.c1)) ON ((a2.c0 = a4.c0) AND a4.c1)) GROUP BY a4.c5, a2.c1;
